// initRepo makes path a git repository with a deterministic identity.
func initRepo(t *testing.T, repo string) {
	t.Helper()
	git(t, repo, "init")
	git(t, repo, "config", "user.name", "Entire Graph Test")
	git(t, repo, "config", "user.email", "graph@example.com")
