use crate::content::language::Language;
use tree_sitter::{Parser, Tree};

/// Parse source code into a tree-sitter AST.
/// Returns None if the language is not supported or parsing fails.
pub fn parse(content: &[u8], language: Language) -> Option<Tree> {
    let ts_language = language_to_grammar(language)?;
    let mut parser = Parser::new();
    parser.set_language(&ts_language).ok()?;
    parser.parse(content, None)
}

/// Map our Language enum to tree-sitter grammar.
/// Returns None for languages we don't have extractors for yet.
fn language_to_grammar(language: Language) -> Option<tree_sitter::Language> {
    match language {
        Language::Go => Some(tree_sitter_go::LANGUAGE.into()),
        Language::Rust => Some(tree_sitter_rust::LANGUAGE.into()),
        Language::Python => Some(tree_sitter_python::LANGUAGE.into()),
        Language::JavaScript => Some(tree_sitter_javascript::LANGUAGE.into()),
        Language::TypeScript => Some(tree_sitter_typescript::LANGUAGE_TYPESCRIPT.into()),
        Language::Java => Some(tree_sitter_java::LANGUAGE.into()),
        Language::C => Some(tree_sitter_c::LANGUAGE.into()),
        Language::Cpp => Some(tree_sitter_cpp::LANGUAGE.into()),
        Language::CSharp => Some(tree_sitter_c_sharp::LANGUAGE.into()),
        Language::Ruby => Some(tree_sitter_ruby::LANGUAGE.into()),
        // Kotlin: tree-sitter-kotlin 0.3.x links against tree-sitter 0.20 (incompatible with 0.26)
        Language::Scala => Some(tree_sitter_scala::LANGUAGE.into()),
        Language::Swift => Some(tree_sitter_swift::LANGUAGE.into()),
        Language::Php => Some(tree_sitter_php::LANGUAGE_PHP.into()),
        Language::Elixir => Some(tree_sitter_elixir::LANGUAGE.into()),
        _ => None,
    }
}

/// Check if we have a tree-sitter grammar for this language.
pub fn is_supported(language: Language) -> bool {
    language_to_grammar(language).is_some()
}

